use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the TemplateVersionVersionAttributeHolder trait.
 *
 * Covers assignment, retrieval, default fallback,
 * transfer between holders, validation rules, and unset operations.
 */
class TemplateVersionVersionAttributeHolderUnitTest extends TestCase
{
        /**
         * Asserts that the code attribute is not assigned by default
         * and that getVersion returns null on a freshly created holder.
         */
        public function testVersionNotAssignedByDefault(): void
        {
            // Arrange
            $holder = new ImplWithTemplateVersionVersionAttributeHolderUnitTest();

            // Assert
            $this->assertFalse($holder->isVersionAssigned());
            $this->assertNull($holder->getVersion());
        }
}
